<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref} from 'vue';import Icon from '../../shared/Icon.vue';
const props=defineProps<{from:string;to:string}>(),emit=defineEmits<{apply:[from:string,to:string]}>(),picker=ref<HTMLDetailsElement>(),panel=ref<HTMLDivElement>();
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const draft=reactive({from:'',to:'',fromMonth:'',toMonth:'',preset:''});const sides=['from','to'] as const;
function init(){Object.assign(draft,{from:props.from,to:props.to,fromMonth:(props.from||today()).slice(0,7),toMonth:(props.to||today()).slice(0,7),preset:''});}
init();
const format=(day:string)=>day.replaceAll('-','/');
function monthAdd(day:string,n:number){const[y,m,d]=day.split('-').map(Number) as[number,number,number];const next=new Date(Date.UTC(y,m-1+n,1));return `${next.getUTCFullYear()}-${String(next.getUTCMonth()+1).padStart(2,'0')}-${String(Math.min(d,new Date(Date.UTC(next.getUTCFullYear(),next.getUTCMonth()+1,0)).getUTCDate())).padStart(2,'0')}`;}
function dayAdd(day:string,n:number){const[y,m,d]=day.split('-').map(Number) as[number,number,number];return new Date(Date.UTC(y,m-1,d+n)).toISOString().slice(0,10);}
function shift(side:'from'|'to',step:number){const key=side==='from'?'fromMonth':'toMonth';draft[key]=monthAdd(draft[key]+'-01',step).slice(0,7);}
const calendars=computed(()=>sides.map(side=>{const month=draft[side==='from'?'fromMonth':'toMonth'],[y,m]=month.split('-').map(Number) as[number,number],days=new Date(Date.UTC(y,m,0)).getUTCDate(),offset=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7;return {side,label:side==='from'?'开始':'结束',year:y,month:m,cells:Array.from({length:42},(_,i)=>{const n=i-offset+1;if(n<1||n>days)return null;const date=month+'-'+String(n).padStart(2,'0');return {n,date,blocked:date>today()||(side==='from'?!!draft.to&&date>draft.to:!!draft.from&&date<draft.from),selected:date===draft[side],inRange:!!draft.from&&!!draft.to&&date>draft.from&&date<draft.to};})};}));
function preset(key:string){const to=today();const months:Record<string,number>={month:1,quarter:3,half:6,year:12};const from=key==='week'?dayAdd(to,-6):key==='ytd'?to.slice(0,4)+'-01-01':dayAdd(monthAdd(to,-months[key]!),1);Object.assign(draft,{from,to,fromMonth:from.slice(0,7),toMonth:to.slice(0,7),preset:key});}
function cancel(){if(picker.value)picker.value.open=false;}
function apply(){if(draft.from&&draft.to&&draft.from>draft.to||draft.from>today()||draft.to>today())return;emit('apply',draft.from,draft.to);cancel();}
function clear(){init();draft.from='';draft.to='';}
function position(){const el=panel.value;if(!el||!picker.value?.open)return;el.style.transform='';el.style.width=Math.min(740,Math.max(0,window.innerWidth-24))+'px';const r=el.getBoundingClientRect(),delta=r.left<12?12-r.left:r.right>window.innerWidth-12?window.innerWidth-12-r.right:0;el.style.transform=`translateX(${delta}px)`;}
function toggle(){if(picker.value?.open){init();requestAnimationFrame(position);}}
function outside(e:MouseEvent){if(!e.composedPath().includes(picker.value!))cancel();}
function escape(e:KeyboardEvent){if(e.key==='Escape')cancel();}
onMounted(()=>{document.addEventListener('click',outside);document.addEventListener('keydown',escape);window.addEventListener('resize',position);});onUnmounted(()=>{document.removeEventListener('click',outside);document.removeEventListener('keydown',escape);window.removeEventListener('resize',position);});
</script>
<template><details ref="picker" class="m19-dropdown m19-date m19-range" @toggle="toggle"><summary class="select" aria-label="会议日期"><span class="m19-range-value" :class="{empty:!from&&!to}">{{format(from)||'开始日期'}} - {{format(to)||'结束日期'}}</span><Icon name="calendar" :size="13"/></summary><div ref="panel" class="m19-range-panel" role="dialog" aria-label="选择会议日期区间"><div class="m19-range-main"><aside class="m19-range-shortcuts" aria-label="时间区间快捷选项"><button v-for="[key,label] in [['week','近一周'],['month','近一月'],['quarter','近三月'],['half','近半年'],['year','近一年'],['ytd','今年以来']]" :key="key" type="button" :class="{active:draft.preset===key}" @click="preset(key!)">{{label}}</button></aside><section v-for="cal in calendars" :key="cal.side" class="m19-range-calendar" :aria-label="cal.label+'日期日历'"><div class="m19-cal-title">{{cal.label}}日期<span>{{format(draft[cal.side])}}</span></div><div class="m19-cal-nav"><button type="button" class="m19-cal-arrow" :aria-label="cal.label+'日历上个月'" @click="shift(cal.side,-1)"><Icon name="arrowL" :size="13"/></button><b>{{cal.year}}年{{cal.month}}月</b><button type="button" class="m19-cal-arrow" :aria-label="cal.label+'日历下个月'" @click="shift(cal.side,1)"><Icon name="arrowR" :size="13"/></button></div><div class="m19-cal-week"><span v-for="day in ['一','二','三','四','五','六','日']" :key="day">{{day}}</span></div><div class="m19-cal-days"><template v-for="(cell,index) in cal.cells" :key="index"><span v-if="!cell" class="m19-cal-blank" aria-hidden="true"></span><button v-else type="button" class="m19-cal-day" :class="{selected:cell.selected,'in-range':cell.inRange}" :aria-label="cal.label+'日期 '+cell.date" :aria-pressed="cell.selected" :disabled="cell.blocked" @click="draft[cal.side]=cell.date;draft.preset=''">{{cell.n}}</button></template></div></section></div><div class="m19-range-footer"><div><button type="button" class="btn sm ghost" @click="clear">清空</button><button type="button" class="btn sm" @click="cancel">取消</button><button type="button" class="btn sm primary" @click="apply">应用</button></div></div></div></details></template>
<style scoped>.m19-cal-day:disabled{opacity:1}</style>
